def is_balanced(text):
    stack = []
    matching = {'(': ')', '[': ']', '{': '}'}
    for char in text:
        if char in matching:
            stack.append(char)
        elif char in matching.values():
            if not stack or matching[stack[-1]] != char:
                return False
            stack.pop()
    return not stack

